import{_ as a,o,c as s,ag as n}from"./chunks/framework.CrXGS008.js";const g=JSON.parse('{"title":"Permisos","description":"","frontmatter":{},"headers":[],"relativePath":"es/nay-lib/permissions.md","filePath":"es/nay-lib/permissions.md"}'),d={name:"es/nay-lib/permissions.md"};function t(c,e,r,i,l,p){return o(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="permisos" tabindex="-1">Permisos <a class="header-anchor" href="#permisos" aria-label="Permalink to &quot;Permisos&quot;">​</a></h1><p>Cada acción de Nayretis que necesita derechos comprueba un <strong>scope</strong>. Los scopes se conceden por ACE, con reglas guardadas en la base de datos o desde la pestaña Permisos de <code>/nay</code>.</p><h2 id="scopes" tabindex="-1">Scopes <a class="header-anchor" href="#scopes" aria-label="Permalink to &quot;Scopes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Concede</th></tr></thead><tbody><tr><td><code>nay.admin</code></td><td>Todo: todos los scripts, los ajustes de Nayretis, los permisos, los tokens de API, los webhooks y el registro de auditoría.</td></tr><tr><td><code>nay.config</code></td><td>Los ajustes de todos los scripts.</td></tr><tr><td><code>nay.audit</code></td><td>El registro de auditoría.</td></tr><tr><td><code>&lt;resource&gt;.config</code></td><td>Los ajustes de un script, por ejemplo <code>nay_car_wash.config</code>.</td></tr><tr><td><code>&lt;resource&gt;.&lt;name&gt;</code></td><td>Un permiso declarado por un script, indicado en su página.</td></tr><tr><td><code>&lt;resource&gt;.*</code></td><td>Todos los scopes de un script. Funciona con reglas (<code>nay_grant</code>), no con ACE.</td></tr></tbody></table><h2 id="con-ace" tabindex="-1">Con ACE <a class="header-anchor" href="#con-ace" aria-label="Permalink to &quot;Con ACE&quot;">​</a></h2><p>Un ACE sobre un scope lo concede. Concede cada scope por su nombre completo (los scopes comodín como <code>nay_car_wash.*</code> solo funcionan como reglas). En <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span>
<span class="line"><span>add_ace group.mod nay_car_wash.config allow</span></span></code></pre></div><h2 id="con-reglas" tabindex="-1">Con reglas <a class="header-anchor" href="#con-reglas" aria-label="Permalink to &quot;Con reglas&quot;">​</a></h2><p>Las reglas se guardan en la base de datos y pueden apuntar directamente a un jugador. Una regla tiene un tipo, un identificador y un scope. Los tipos son:</p><ul><li><code>ace</code>: todos los jugadores autorizados en ese objeto ACE;</li><li><code>discord</code>, <code>steam</code>, <code>fivem</code>, <code>license</code>: un jugador, por identificador.</li></ul><p>Desde la consola del servidor:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license 1a2b3c4d5e6f nay.admin</span></span>
<span class="line"><span>nay_grant discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_revoke discord 123456789012345678 nay_car_wash.config</span></span>
<span class="line"><span>nay_rules</span></span></code></pre></div><p><code>nay_grant</code> y <code>nay_revoke</code> reciben <code>&lt;ace|discord|steam|fivem|license&gt; &lt;identifier&gt; &lt;scope&gt;</code>. <code>nay_rules</code> lista todas las reglas con su número.</p><p>En el juego, la pestaña <strong>Permisos</strong> de <code>/nay</code> (scope <code>nay.admin</code>) lista, añade y elimina esas mismas reglas. Cada cambio se anota en el <a href="/es/nay-lib/audit">registro de auditoría</a>.</p>`,14)])])}const m=a(d,[["render",t]]);export{g as __pageData,m as default};
